{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 6,
      "verse": 28,
      "source_ref": "6:28",
      "text_ar": "وكان الفُلك يطفو على سطح المياه، وكان يُقذف في المياه بحيث تدور جميع المخلوقات الحية داخله كالحساء في قدر."
    },
    {
      "chapter": 6,
      "verse": 29,
      "source_ref": "6:29",
      "text_ar": "وشعور بالقلق الشديد أصاب جميع المخلوقات الحية التي في الفُلك، وكان الفُلك كأنه سيتكسر."
    },
    {
      "chapter": 6,
      "verse": 30,
      "source_ref": "6:30",
      "text_ar": "ارتعبت جميع المخلوقات الحية التي في الفُلك، وصاحت الأسود، وزئرت الثيران، وعوت الذئاب، وتكلم كل مخلوق حي في الفُلك ونحى بلغته الخاصة، فت وصلت أصواتهم إلى مسافة كبيرة، فبكى نوح وأبناؤه في مشكلاتهم؛ كانوا خائفين كثيرًا أنهم وصلوا إلى أبواب الموت."
    },
    {
      "chapter": 6,
      "verse": 31,
      "source_ref": "6:31",
      "text_ar": "فصلى نوح إلى الرب، وناحه بسببه، وقال: يا رب أعننا، فلا قوة لنا على تحمل هذا الشر الذي أحاط بنا، فالأمواج قد أحاطتنا، والفيضانات المخيفة أرعبتنا، وفخاخ الموت قُدمت أمامنا؛ أجبنا يا رب، أجبنا، أنر وجهك نحونا وكن رحيماً بنا، فدنا وانقذنا."
    },
    {
      "chapter": 6,
      "verse": 32,
      "source_ref": "6:32",
      "text_ar": "فاستمع الرب لصوت نوح، وتذكره الرب."
    }
  ]
}
